#!/usr/bin/env python3
# Append French A2 Unit 05 (sequences 25-30) as one guarded batch.
from __future__ import annotations
import base64,json,re,subprocess,zlib
from jsonschema import Draft202012Validator
import generate_french_a2_unit03 as base
A1=base.A1; CANON=base.CANON; SCHEMA=base.SCHEMA
EXPECTED_A1_BLOB="0493a2fa13e51b5997db05e91cdea4d8dc5e647b"
EXPECTED_BLOB="19bee388edfc203eaecdcaabf640a776e9828212"
FORMS=("médecin","patient","douleur","santé","hôpital","accident","soin","urgence","risque","danger")
DATA=json.loads(zlib.decompress(base64.b64decode("")))
def mk(s,new,reviews,ids,speed=False):
 q,a=base.qa(s["items"],ids); text=s["text"]
 return {"id":s["id"],"language":"fr","cefr":"A2","unit":5,"sequence":s["sequence"],"revision":1,"title":s["title"],"passage_type":s["ptype"],"genre":s["genre"],"domains":s["domains"],"topics":s["topics"],"text":text,"word_count":len(text.split()),"sentence_count":max(1,len(re.findall(r"[.!?](?:[»”\"])?",text))),"estimated_known_token_coverage":0,"new_lexical_targets":new,"review_lexical_targets":reviews,"grammar_targets":s["grammar"],"discourse_targets":s["discourse"],"questions":q,"answer_key":a,"speed_training":{"timed":speed,"benchmark_eligible":speed,"comprehension_gate":0.8,"new_word_policy":"none" if speed else "controlled","notes":"Generation-stage French A2 Unit 05; final language-wide audit deferred."},"quality":{"status":"draft","schema_check":"pending","linguistic_review":"pending","pedagogical_review":"pending","answer_key_check":"pending","coverage_check":"pending","fact_check":"not_required","notes":["Guarded French A2 Unit 05 generation batch.","A1+A2 freshness, source identity, A2 word band, review visibility, local target linkage, continuity and zero-new checkpoint are enforced."]},"paired_text_group":None,"prerequisites":["French A2 Units 01-04 canonical corpus"],"difficulty_notes_internal":"A2 everyday health and safety situations using general non-diagnostic language, cause/effect, reference chains and practical decisions.","reader_tags":["unit_role:"+s["ptype"],"generation_batch","french_a2_u05"]}
def build(rows,a1,D):
 P=base.prior(a1+rows); bad=[]
 for f in FORMS:
  if f not in D: bad.append(f+":missing_lexicon")
  if P.get(f): bad.append(f+":already_deliberate")
 if bad: raise AssertionError("Unit05 candidate failures: "+", ".join(bad))
 out=[]
 for s in DATA["specs"]:
  new=[base.nt(f,s["text"],D) for f in s["forms"]]; reviews=[base.rev(f,P) for f in s["reviews"]]; ids={t["form"]:t["id"] for t in new+reviews}; out.append(mk(s,new,reviews,ids))
 s=DATA["checkpoint"]; reviews=[base.cur(f,D) for f in FORMS]; ids={t["form"]:t["id"] for t in reviews}; out.append(mk(s,[],reviews,ids,True)); return out
def main():
 a1_blob=subprocess.check_output(["git","hash-object",str(A1)],text=True).strip(); blob=subprocess.check_output(["git","hash-object",str(CANON)],text=True).strip()
 if a1_blob!=EXPECTED_A1_BLOB: raise AssertionError(f"A1 blob drift: {a1_blob} != {EXPECTED_A1_BLOB}")
 if blob!=EXPECTED_BLOB: raise AssertionError(f"A2 blob drift: {blob} != {EXPECTED_BLOB}")
 a1=[json.loads(x) for x in A1.read_text(encoding="utf-8").splitlines() if x.strip()]; rows=[json.loads(x) for x in CANON.read_text(encoding="utf-8").splitlines() if x.strip()]
 if len(rows)!=24 or [r["sequence"] for r in rows]!=list(range(1,25)) or rows[-1]["id"]!="fr-a2-u04-p06": raise AssertionError("expected exact A2 frontier through Unit04")
 D=base.deck(); unit=build(rows,a1,D); V=Draft202012Validator(json.loads(SCHEMA.read_text(encoding="utf-8")))
 if [r["sequence"] for r in unit]!=list(range(25,31)) or len({r["id"] for r in rows+unit})!=30: raise AssertionError("Unit05 continuity failure")
 old_ids={t["id"] for r in a1+rows for t in r.get("new_lexical_targets",[]) if isinstance(t,dict) and t.get("id")}; new_ids=[]
 for r in unit:
  errs=sorted(V.iter_errors(r),key=lambda e:list(e.path))
  if errs: raise AssertionError(f"{r['id']}: schema {[e.message for e in errs[:6]]}")
  if not 140<=r["word_count"]<=220: raise AssertionError(f"{r['id']}: word band {r['word_count']}")
  if len(r["questions"])!=10 or len(r["answer_key"])!=10: raise AssertionError(f"{r['id']}: assessment count")
  amap={a["question_id"]:a["id"] for a in r["answer_key"]}; local={t["id"] for fld in ("new_lexical_targets","review_lexical_targets") for t in r.get(fld,[]) if isinstance(t,dict)}
  if len(amap)!=10: raise AssertionError(f"{r['id']}: answer mapping count")
  for q in r["questions"]:
   if amap.get(q["id"])!=q["answer_id"]: raise AssertionError(f"{r['id']} {q['id']}: linkage")
   if any(x not in local for x in q.get("target_ids",[])): raise AssertionError(f"{r['id']} {q['id']}: undeclared target")
  for t in r["new_lexical_targets"]:
   if t["id"] in old_ids: raise AssertionError(f"{r['id']}: reintroduced {t['id']}")
   s=D.get(t["form"])
   if not s or t["source_rank"]!=s["rank"] or t["id"]!=base.tid(s["rank"]): raise AssertionError(f"{r['id']}: source identity {t['form']}")
   if base.cnt(r["text"],t["form"])!=t["exposures_in_text"]: raise AssertionError(f"{r['id']}: exposure mismatch {t['form']}")
   new_ids.append(t["id"])
  for t in r["review_lexical_targets"]:
   if t["representation"] in {"running_text","summary"} and base.cnt(r["text"],t["form"])<1: raise AssertionError(f"{r['id']}: invisible review {t['form']}")
 if len(new_ids)!=10 or len(set(new_ids))!=10 or unit[-1]["new_lexical_targets"]!=[]: raise AssertionError("Unit05 lexical-cycle invariant")
 original=CANON.read_text(encoding="utf-8"); original += "" if original.endswith("\n") else "\n"; CANON.write_text(original+"".join(json.dumps(r,ensure_ascii=False,sort_keys=True)+"\n" for r in unit),encoding="utf-8")
 final=[json.loads(x) for x in CANON.read_text(encoding="utf-8").splitlines() if x.strip()]
 if len(final)!=30 or [r["sequence"] for r in final]!=list(range(1,31)): raise AssertionError("post-write continuity failure")
 print(json.dumps({"status":"PASS","unit":5,"appended_passages":6,"french_a2_total":30,"word_counts":{r["id"]:r["word_count"] for r in unit},"new_targets":10,"questions":60,"answers":60,"checkpoint_new_targets":0},ensure_ascii=False))
if __name__=="__main__": main()
